function moveItem(arr,from,to){if(to<0||to>=arr.length)return;const [x]=arr.splice(from,1);arr.splice(to,0,x);}

/* Skills editor actions — editor data only; public Skills markup/classes stay unchanged. */
function bindSkillsEditor(){
  const host=document.getElementById("skillsEditor");
  if(!host || host.dataset.bound==="1")return;
  host.dataset.bound="1";
  host.addEventListener("click",e=>{
    const button=e.target.closest("button");
    if(!button)return;
    e.preventDefault();
    const skillUp=button.dataset.skillUp;
    const skillDown=button.dataset.skillDown;
    const skillDelete=button.dataset.skillDelete;
    const skillAdd=button.dataset.skillAdd;
    const categoryUp=button.dataset.categoryUp;
    const categoryDown=button.dataset.categoryDown;
    const categoryDelete=button.dataset.categoryDelete;
    const categoryAdd=button.dataset.categoryAdd!==undefined;
    const languageUp=button.dataset.languageUp;
    const languageDown=button.dataset.languageDown;
    const languageDelete=button.dataset.languageDelete;
    const languageAdd=button.dataset.languageAdd!==undefined;

    // Keep text edits already entered in the form before rebuilding the editor UI.
    if(skillUp || skillDown || skillDelete || skillAdd || categoryUp || categoryDown || categoryDelete || categoryAdd || languageUp || languageDown || languageDelete || languageAdd){
      readSkillsEditor();
    }

    if(skillUp || skillDown || skillDelete){
      const [ciRaw,iiRaw]=(skillUp||skillDown||skillDelete).split(":");
      const ci=Number(ciRaw), ii=Number(iiRaw);
      const items=state.skills.categories[ci]?.items;
      if(!items)return;
      if(skillUp)moveItem(items,ii,ii-1);
      else if(skillDown)moveItem(items,ii,ii+1);
      else if(skillDelete)items.splice(ii,1);
      buildSkillsEditor();
      return;
    }

    if(skillAdd){
      const ci=Number(skillAdd);
      if(!state.skills.categories[ci])return;
      state.skills.categories[ci].items.push("NEW SKILL");
      buildSkillsEditor();
      const rows=host.querySelectorAll(`[data-skill-add="${ci}"]`);
      const section=rows[0]?.closest(".skill-editor-category");
      section?.querySelector(".skill-editor-items input:last-child")?.focus();
      return;
    }

    if(categoryUp || categoryDown || categoryDelete){
      const ci=Number(categoryUp||categoryDown||categoryDelete);
      if(!Number.isInteger(ci)||!state.skills.categories[ci])return;
      if(categoryUp)moveItem(state.skills.categories,ci,ci-1);
      else if(categoryDown)moveItem(state.skills.categories,ci,ci+1);
      else state.skills.categories.splice(ci,1);
      buildSkillsEditor();
      return;
    }

    if(categoryAdd){
      state.skills.categories.push({name:"NEW CATEGORY",items:["NEW SKILL"]});
      buildSkillsEditor();
      return;
    }

    if(languageUp || languageDown || languageDelete){
      const i=Number(languageUp||languageDown||languageDelete);
      if(!Number.isInteger(i)||!state.skills.languages[i])return;
      if(languageUp)moveItem(state.skills.languages,i,i-1);
      else if(languageDown)moveItem(state.skills.languages,i,i+1);
      else state.skills.languages.splice(i,1);
      buildSkillsEditor();
      return;
    }

    if(languageAdd){
      state.skills.languages.push("NEW LANGUAGE");
      buildSkillsEditor();
    }
  });
}

async function renderContentCarousel(box, metaItems, sectionKey){
  const staticPaths=STATIC_MEDIA[sectionKey]||[];
  const entries=[];
  if(metaItems.length){
    for(const meta of metaItems.slice(0,20)){
      try{
        const pending=pendingMediaFiles[mediaStorageKey(sectionKey,meta.id)];
        const file=pending ? {blob:pending,type:isVideoFile(pending)?"video":"image"} : await getManagedMedia(sectionKey,meta.id,meta);
        if(file) entries.push({meta:{...meta,format:"Original",customRatio:""},file,src:file.legacy?file.src:null});
      }catch(err){console.error("CHERRY LINE content carousel media read error",sectionKey,meta.id,err)}
    }
  }
  if(!entries.length){
    for(const path of staticPaths.slice(0,20)){
      const isVideo=/\.(mp4|mov|webm|m4v)$/i.test(path);
      // Sport Content 1 and 3 are hosted on YouTube, so don't load their large local copies.
      if(sectionKey==="sport1" && (/Sportcontent1\.mov$/i.test(path) || /Sportcontent3\.mov$/i.test(path))) continue;
      const loaded=await checkStaticMedia(path,isVideo);
      if(loaded) entries.push({path,isVideo,meta:{format:"Original",customRatio:""}});
    }
  }
  // The corresponding Sport Content 1 and 3 local files are replaced by their YouTube versions.
  if(sectionKey==="sport1"){
    for(let i=entries.length-1;i>=0;i--){
      const name=String(entries[i].meta?.name||entries[i].meta?.filename||entries[i].meta?.src||entries[i].path||"");
      if(/sportcontent[13]\.(mov|mp4|webm|m4v)$/i.test(name)) entries.splice(i,1);
    }
  }
  // Add hosted videos to the carousel while preserving each video's native orientation.
  for(const hosted of (YOUTUBE_MEDIA[sectionKey]||[])){
    if(hosted.instagramUrl){
      if(!entries.some(entry=>entry.instagramUrl===hosted.instagramUrl)) entries.push({instagramUrl:hosted.instagramUrl,ratio:hosted.ratio||"9 / 16",label:hosted.label,meta:{format:"Original",customRatio:""}});
    }else if(!entries.some(entry=>entry.youtubeId===hosted.id)) entries.push({youtubeId:hosted.id,ratio:hosted.ratio,label:hosted.label,meta:{format:"Original",customRatio:""}});
  }
  box.innerHTML="";
  box.classList.add("content-carousel-host","media-managed-host");
  box.classList.remove("media-managed-multi");
  box.style.removeProperty("aspect-ratio");
  box.style.removeProperty("width");
  box.style.removeProperty("height");
  box.style.setProperty("height","auto","important");
  box.style.setProperty("aspect-ratio","auto","important");
  box.style.setProperty("overflow","visible","important");
  if(!entries.length){box.classList.add("content-carousel-empty");box.textContent="MEDIA COMING SOON";return;}
  const stage=document.createElement("div");stage.className="content-carousel-stage";
  const stageHeight=window.innerWidth<600?300:420;
  stage.style.setProperty("height",`${stageHeight}px`,"important");
  const track=document.createElement("div");track.className="content-carousel-track";
  const prev=document.createElement("button");prev.type="button";prev.className="content-carousel-arrow content-carousel-prev";prev.setAttribute("aria-label","Previous media");prev.textContent="‹";
  const next=document.createElement("button");next.type="button";next.className="content-carousel-arrow content-carousel-next";next.setAttribute("aria-label","Next media");next.textContent="›";
  const counter=document.createElement("span");counter.className="content-carousel-counter";
  const dots=document.createElement("div");dots.className="content-carousel-dots";
  stage.appendChild(track);box.append(stage,counter);
  let index=0;const slides=[];
  function makeMedia(entry,i){
    const frame=document.createElement("div");frame.className="content-carousel-slide";frame.dataset.index=String(i);
    let src=entry.src;if(entry.file&&!entry.file.legacy)src=URL.createObjectURL(entry.file.blob||entry.file);
    const applyRatio=(el,w,h)=>{if(!w||!h)return;const ratio=w/h;const stageH=stageHeight;let height=stageH,width=height*ratio;const maxWidth=Math.max(180,Math.min(window.innerWidth*.78,900));if(width>maxWidth){width=maxWidth;height=width/ratio;}frame.style.width=`${Math.round(width)}px`;frame.style.height=`${Math.round(height)}px`;};
    if(entry.youtubeId || entry.instagramUrl){
      const ratio=entry.ratio||(entry.instagramUrl?"9 / 16":"16 / 9"); const parts=ratio.split("/").map(v=>Number(v.trim())); const rw=parts[0]||16,rh=parts[1]||9;
      const stageH=stageHeight; let height=stageH,width=height*rw/rh;
      const maxWidth=Math.max(180,Math.min(window.innerWidth*.78,900)); if(width>maxWidth){width=maxWidth;height=width/(rw/rh);}
      frame.style.width=`${Math.round(width)}px`; frame.style.height=`${Math.round(height)}px`; frame.classList.add(entry.instagramUrl?"content-carousel-instagram":"content-carousel-youtube");
      const iframe=document.createElement("iframe"); iframe.className="youtube-embed-frame";
      iframe.src=entry.instagramUrl?`${entry.instagramUrl.replace(/\/$/,"")}/embed`:`https://www.youtube-nocookie.com/embed/${entry.youtubeId}?playsinline=1&rel=0&autoplay=1&mute=1&controls=0&loop=1&playlist=${entry.youtubeId}`; iframe.title=entry.label||"Embedded video"; iframe.loading="eager";
      iframe.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"; iframe.allowFullscreen=true; iframe.referrerPolicy="strict-origin-when-cross-origin";
      frame.appendChild(iframe);
      if(entry.instagramUrl){const fallback=document.createElement("a");fallback.className="content-carousel-external-link";fallback.href=entry.instagramUrl;fallback.target="_blank";fallback.rel="noopener noreferrer";fallback.textContent="Open Reel on Instagram ↗";frame.appendChild(fallback);}
    }
    else {
      const type=entry.isVideo||entry.file?.type==="video"||String(entry.file?.type||"").startsWith("video/");
      if(type){const video=document.createElement("video");video.src=src||entry.path;video.playsInline=true;video.preload="auto";video.muted=true;video.defaultMuted=true;video.loop=true;video.autoplay=true;video.controls=true;video.setAttribute("playsinline","");video.setAttribute("muted","");video.setAttribute("autoplay","");video.addEventListener("loadedmetadata",()=>applyRatio(video,video.videoWidth,video.videoHeight),{once:true});video.addEventListener("loadeddata",()=>{const playPromise=video.play();if(playPromise&&typeof playPromise.catch==="function")playPromise.catch(()=>{});},{once:true});video.addEventListener("error",()=>{frame.classList.add("content-carousel-media-error");video.remove();frame.textContent="MEDIA UNAVAILABLE"},{once:true});frame.appendChild(video);}
      else{const img=document.createElement("img");img.alt=`${sectionKey==="sport1"?"Sport":"School"} content ${i+1}`;img.loading="lazy";img.src=src||entry.path;img.addEventListener("load",()=>applyRatio(img,img.naturalWidth,img.naturalHeight),{once:true});img.addEventListener("error",()=>{frame.classList.add("content-carousel-media-error");img.remove();frame.textContent="MEDIA UNAVAILABLE"},{once:true});frame.appendChild(img);}
    }
    return frame;
  }
  entries.forEach((entry,i)=>{const slide=makeMedia(entry,i);slides.push(slide);track.appendChild(slide)});
  let firstClone=null,lastClone=null;
  if(slides.length>1){
    lastClone=slides[slides.length-1].cloneNode(true);lastClone.classList.add("is-loop-clone");lastClone.dataset.loopClone="last";
    firstClone=slides[0].cloneNode(true);firstClone.classList.add("is-loop-clone");firstClone.dataset.loopClone="first";
    track.insertBefore(lastClone,slides[0]);track.appendChild(firstClone);
  }
  function setActive(nextIndex,scroll=true){
    index=(nextIndex+entries.length)%entries.length;
    slides.forEach((slide,i)=>slide.classList.toggle("is-active",i===index));
    counter.textContent=`${index+1} / ${entries.length}`;
    if(scroll){const slide=slides[index];stage.scrollTo({left:slide.offsetLeft-(stage.clientWidth-slide.clientWidth)/2,behavior:"smooth"});}
  }
  // Native horizontal scrolling + snap; cloned edge slides make the wrap seamless.
  // When the user lands on a clone, jump to its identical original with no animation.
  if(slides.length>1){
    requestAnimationFrame(()=>{stage.scrollLeft=slides[0].offsetLeft-(stage.clientWidth-slides[0].clientWidth)/2;});
  }
  // Native horizontal scrolling + snap provides smooth swipe navigation without arrows/dots.
  // Don't force a second scroll on touchend: that caused the visible reverse/bounce effect.
  let scrollTimer=null;
  stage.addEventListener("scroll",()=>{
    if(scrollTimer)clearTimeout(scrollTimer);
    scrollTimer=setTimeout(()=>{
      if(!slides.length)return;
      const children=Array.from(track.children);const center=stage.scrollLeft+stage.clientWidth/2;let childIndex=0,distance=Infinity;
      children.forEach((slide,i)=>{const d=Math.abs(slide.offsetLeft+slide.clientWidth/2-center);if(d<distance){distance=d;childIndex=i}});
      if(children[childIndex]?.dataset.loopClone==="last"){
        const target=slides[slides.length-1];stage.scrollTo({left:target.offsetLeft-(stage.clientWidth-target.clientWidth)/2,behavior:"auto"});index=slides.length-1;
      }else if(children[childIndex]?.dataset.loopClone==="first"){
        const target=slides[0];stage.scrollTo({left:target.offsetLeft-(stage.clientWidth-target.clientWidth)/2,behavior:"auto"});index=0;
      }else index=Math.max(0,Math.min(slides.length-1,childIndex-1));
      slides.forEach((slide,i)=>slide.classList.toggle("is-active",i===index));counter.textContent=`${index+1} / ${entries.length}`;
    },80);
  },{passive:true});
  requestAnimationFrame(()=>setActive(0,false));
}

function checkStaticMedia(path,isVideo){
  return new Promise(resolve=>{
    const el=document.createElement(isVideo?"video":"img");
    let done=false; const finish=value=>{if(done)return;done=true;el.removeAttribute("src");resolve(value)};
    el.onload=()=>finish(true); el.onerror=()=>finish(false);
    if(isVideo){el.preload="metadata";el.onloadedmetadata=()=>finish(true);}
    el.src=path;
    setTimeout(()=>finish(false),7000);
  });
}

async function renderAboutCarousel(box,items,sectionKey="about"){
  box.innerHTML="";
  box.classList.add("media-managed-host","about-carousel-host");
  box.classList.remove("media-managed-multi");
  const viewport=document.createElement("div"); viewport.className="about-carousel-viewport";
  const track=document.createElement("div"); track.className="about-carousel-track";
  const dots=document.createElement("div"); dots.className="about-carousel-dots";
  const prev=document.createElement("button"); prev.type="button"; prev.className="about-carousel-arrow about-carousel-prev"; prev.setAttribute("aria-label","Previous photo"); prev.textContent="‹";
  const next=document.createElement("button"); next.type="button"; next.className="about-carousel-arrow about-carousel-next"; next.setAttribute("aria-label","Next photo"); next.textContent="›";
  const slides=[];
  // Keep all four About slots in the carousel. A single unreadable/missing file
  // must never make the remaining photos disappear or reduce the carousel to 3.
  const maxItems=sectionKey==="about"?4:20;
  // SPORT and SCHOOL frames follow the actual uploaded media ratio. Older saved
  // 9:16 metadata is ignored for these two slots so landscape/square uploads are not cropped.
  const frameMeta=(meta)=>((sectionKey==="sport1"||sectionKey==="school1")?{...meta,format:"Original",customRatio:""}:(sectionKey==="about"?{...meta,format:"9:16",customRatio:""}:meta));
  for(const meta of items.slice(0,maxItems)){
    const displayMeta=frameMeta(meta);
    let file=null;
    try{
      if(sectionKey==="about" && meta.src){
        file={legacy:true,src:meta.src,type:"image"};
      }else{
        const pending=pendingMediaFiles[mediaStorageKey(sectionKey,meta.id)];
        file=pending ? {blob:pending,type:isVideoFile(pending)?"video":"image"} : await getManagedMedia(sectionKey,meta.id,meta);
      }
    }catch(err){console.error("CHERRY LINE carousel media read error",sectionKey,meta.id,err)}
    const slide=document.createElement("div"); slide.className="about-carousel-slide";
    if(!file){
      slide.classList.add("about-carousel-missing");
      slide.textContent=`${sectionKey.toUpperCase()} MEDIA ${String(slides.length+1).padStart(2,"0")} — UNAVAILABLE`;
    }else{
      const src=file.legacy?file.src:URL.createObjectURL(file.blob); if(!file.legacy)slide.dataset.objectUrl=src;
      if(file.type==="video" || String(file.type||"").startsWith("video/")){
        const v=attachSafeVideo(document.createElement("video"),slide,displayMeta);
        v.addEventListener("loadedmetadata",()=>{
          if(slide.classList.contains("is-active"))sizeContentCarouselToMedia(box,displayMeta,v.videoWidth,v.videoHeight);
        },{once:true});
        v.preload="auto";v.autoplay=true;v.loop=true;v.muted=true;v.defaultMuted=true;v.setAttribute("autoplay","");v.setAttribute("muted","");v.addEventListener("loadeddata",()=>{const playPromise=v.play();if(playPromise&&typeof playPromise.catch==="function")playPromise.catch(()=>{});},{once:true});v.src=src; slide.appendChild(v);
      }else{
        const img=document.createElement("img"); img.alt=""; img.src=src;
        img.addEventListener("load",()=>{
          applyMediaRatio(slide,displayMeta,img.naturalWidth,img.naturalHeight);
          if(slide.classList.contains("is-active"))sizeContentCarouselToMedia(box,displayMeta,img.naturalWidth,img.naturalHeight);
        },{once:true});
        slide.appendChild(img);
      }
    }
    /* The outer carousel frame owns the selected ratio. Slides fill it;
       applying a second ratio here caused square content inside portrait frames. */
    track.appendChild(slide); slides.push({slide,meta:displayMeta});
  }
  if(!slides.length){box.textContent="ADD ABOUT PHOTO 01";return}
  if(slides.length>1){
    const lastClone=slides[slides.length-1].slide.cloneNode(true);lastClone.classList.add("about-loop-clone");
    const firstClone=slides[0].slide.cloneNode(true);firstClone.classList.add("about-loop-clone");
    track.insertBefore(lastClone,slides[0].slide);track.appendChild(firstClone);
  }
  viewport.appendChild(track); box.append(viewport);
  let index=0, pendingLoopReset=null;
  const setActive=(nextIndex)=>{
    let trackIndex;
    if(slides.length>1 && nextIndex>=slides.length){index=0;trackIndex=slides.length+1;pendingLoopReset=1;}
    else if(slides.length>1 && nextIndex<0){index=slides.length-1;trackIndex=0;pendingLoopReset=slides.length;}
    else {index=(nextIndex+slides.length)%slides.length;trackIndex=index+1;pendingLoopReset=null;}
    track.style.transform=`translate3d(-${trackIndex*viewport.clientWidth}px,0,0)`;
    slides.forEach((entry,i)=>entry.slide.classList.toggle("is-active",i===index));
    const active=slides[index];
    const img=active.slide.querySelector("img");
    const video=active.slide.querySelector("video");
    if(img?.naturalWidth&&img?.naturalHeight)sizeContentCarouselToMedia(box,active.meta,img.naturalWidth,img.naturalHeight);
    else if(video?.videoWidth&&video?.videoHeight)sizeContentCarouselToMedia(box,active.meta,video.videoWidth,video.videoHeight);
    else sizeContentCarouselToMedia(box,active.meta);
  };
  track.addEventListener("transitionend",()=>{
    if(pendingLoopReset===null)return;
    const resetTo=pendingLoopReset;pendingLoopReset=null;
    track.style.transition="none";track.style.transform=`translate3d(-${resetTo*viewport.clientWidth}px,0,0)`;
    void track.offsetHeight;track.style.transition="";
  });
  let swipeStartX=0, swipeStartY=0;
  viewport.addEventListener("touchstart",e=>{swipeStartX=e.changedTouches[0]?.clientX||0;swipeStartY=e.changedTouches[0]?.clientY||0},{passive:true});
  viewport.addEventListener("touchend",e=>{const dx=(e.changedTouches[0]?.clientX||0)-swipeStartX;const dy=(e.changedTouches[0]?.clientY||0)-swipeStartY;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy)*1.2)setActive(index+(dx<0?1:-1));},{passive:true});
  let pointerStartX=0,pointerStartY=0;
  viewport.addEventListener("pointerdown",e=>{if(e.pointerType==="mouse"){pointerStartX=e.clientX;pointerStartY=e.clientY;} });
  viewport.addEventListener("pointerup",e=>{if(e.pointerType!=="mouse")return;const dx=e.clientX-pointerStartX,dy=e.clientY-pointerStartY;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy)*1.2)setActive(index+(dx<0?1:-1));});
  window.addEventListener("resize",()=>{track.style.transition="none";setActive(index);void track.offsetHeight;track.style.transition="";});
  setActive(0);
}

